head.script:
//
{
  "@context": "https://schema.org",
  "@type": "WebApplication",
  "name": "Shikhon Shala (শিখনশালা)",
  "alternateName": "শিখনশালা বাংলা টাইপিং প্ল্যাটফর্ম",
  "applicationCategory": "EducationalApplication",
  "operatingSystem": "Web Browser",
  "inLanguage": ["bn", "en"],
  "isAccessibleForFree": true,
  "description": "Free interactive Bijoy Bangla typing tutor supporting Bijoy Unicode and Bijoy Classic ANSI with 12 lessons, visual keyboard, speed tests, and typing games."
}
//

head.b:skin:
/*
-----------------------------------------------
Blogger Template Name: Shikhon Shala (শিখনশালা)
Version: 1.0.0
Author: Shikhon Shala Team
Description: Free Bangla Bijoy Typing Learning Platform
-----------------------------------------------
*/

/* Variable definitions for Blogger Theme Designer
   ====================
   <Variable name="brand.emerald" description="Primary Accent Green" type="color" default="#059669" value="#059669"/>
   <Variable name="brand.navy" description="Dark Navy Surface" type="color" default="#0B1526" value="#0B1526"/>
   <Variable name="canvas.bg" description="Light Canvas Background" type="color" default="#F8FAFC" value="#F8FAFC"/>
*/

:root {
  --ss-bg: #F8FAFC;
  --ss-surface: #FFFFFF;
  --ss-surface-muted: #F1F5F9;
  --ss-border: #E2E8F0;
  --ss-text: #0F172A;
  --ss-text-muted: #475569;
  --ss-navy: #0B1526;
  --ss-emerald: #059669;
  --ss-emerald-hover: #047857;
  --ss-emerald-soft: #ECFDF5;
  --ss-emerald-text: #065F46;
  --ss-danger: #DC2626;
  --ss-danger-soft: #FEF2F2;
  --ss-amber: #D97706;
  --ss-amber-soft: #FFFBEB;
  --ss-shadow: 0 1px 3px rgba(15, 23, 42, 0.06), 0 1px 2px rgba(15, 23, 42, 0.04);
  --ss-font-sans: 'Plus Jakarta Sans', 'Noto Sans Bengali', system-ui, -apple-system, sans-serif;
  --ss-font-bn: 'Noto Sans Bengali', 'SolaimanLipi', 'Kalpurush', sans-serif;
  --ss-font-mono: 'JetBrains Mono', ui-monospace, monospace;
}

[data-theme="dark"] {
  --ss-bg: #0B1526;
  --ss-surface: #111E33;
  --ss-surface-muted: #172742;
  --ss-border: #1E3252;
  --ss-text: #F1F5F9;
  --ss-text-muted: #94A3B8;
  --ss-navy: #060D18;
  --ss-emerald: #10B981;
  --ss-emerald-hover: #34D399;
  --ss-emerald-soft: rgba(16, 185, 129, 0.14);
  --ss-emerald-text: #6EE7B7;
  --ss-danger: #F87171;
  --ss-danger-soft: rgba(239, 68, 68, 0.14);
  --ss-amber: #FBBF24;
  --ss-amber-soft: rgba(245, 158, 11, 0.14);
  --ss-shadow: 0 2px 6px rgba(0, 0, 0, 0.28);
}

*, *::before, *::after {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  background-color: var(--ss-bg);
  color: var(--ss-text);
  font-family: var(--ss-font-sans);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--ss-emerald);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

button, input, textarea, select {
  font-family: inherit;
}

:focus-visible {
  outline: 2px solid var(--ss-emerald);
  outline-offset: 2px;
}

.ss-bn {
  font-family: var(--ss-font-bn);
}

.ss-mono {
  font-family: var(--ss-font-mono);
  font-variant-numeric: tabular-nums;
}

/* Shell Layout */
.ss-shell {
  display: flex;
  min-height: 100vh;
}

.ss-sidebar {
  width: 268px;
  flex-shrink: 0;
  background: var(--ss-navy);
  color: #E2E8F0;
  display: flex;
  flex-direction: column;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
  z-index: 40;
}

.ss-brand-box {
  padding: 20px 20px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.ss-brand-title {
  margin: 0;
  font-size: 20px;
  font-weight: 800;
  color: #FFFFFF;
  letter-spacing: -0.02em;
}

.ss-brand-title a {
  color: #FFFFFF;
  text-decoration: none;
}

.ss-brand-sub {
  margin: 4px 0 0;
  font-size: 12px;
  color: #94A3B8;
  font-family: var(--ss-font-bn);
}

.ss-nav-list {
  list-style: none;
  margin: 0;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}

.ss-nav-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #CBD5E1;
  font-size: 14px;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
  white-space: nowrap;
}

.ss-nav-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #FFFFFF;
}

.ss-nav-btn.is-active {
  background: var(--ss-emerald);
  color: #FFFFFF;
  font-weight: 600;
}

.ss-sidebar-footer {
  padding: 14px 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 12px;
  color: #94A3B8;
}

.ss-main-area {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.ss-topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  background: var(--ss-surface);
  border-bottom: 1px solid var(--ss-border);
  padding: 12px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.ss-topbar-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ss-mobile-toggle {
  display: none;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--ss-border);
  background: var(--ss-surface-muted);
  color: var(--ss-text);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.ss-topbar-controls {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.ss-segmented {
  display: inline-flex;
  background: var(--ss-surface-muted);
  border: 1px solid var(--ss-border);
  border-radius: 9px;
  padding: 3px;
  gap: 2px;
}

.ss-seg-btn {
  border: 0;
  background: transparent;
  color: var(--ss-text-muted);
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.ss-seg-btn.is-active {
  background: var(--ss-surface);
  color: var(--ss-emerald);
  box-shadow: var(--ss-shadow);
}

.ss-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 16px;
  border-radius: 9px;
  border: 1px solid var(--ss-border);
  background: var(--ss-surface);
  color: var(--ss-text);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.ss-btn:hover {
  background: var(--ss-surface-muted);
}

.ss-btn-primary {
  background: var(--ss-emerald);
  border-color: var(--ss-emerald);
  color: #FFFFFF;
}

.ss-btn-primary:hover {
  background: var(--ss-emerald-hover);
  border-color: var(--ss-emerald-hover);
}

.ss-btn-danger {
  color: var(--ss-danger);
  border-color: rgba(220, 38, 38, 0.3);
}

.ss-content {
  padding: 24px;
  max-width: 1180px;
  width: 100%;
  margin: 0 auto;
  flex: 1;
}

/* Cards & Grids */
.ss-card {
  background: var(--ss-surface);
  border: 1px solid var(--ss-border);
  border-radius: 14px;
  padding: 20px;
  box-shadow: var(--ss-shadow);
}

.ss-grid {
  display: grid;
  gap: 16px;
}

.ss-grid-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.ss-grid-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.ss-grid-4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.ss-hero {
  background: linear-gradient(135deg, var(--ss-navy) 0%, #13284A 100%);
  color: #FFFFFF;
  border-radius: 16px;
  padding: 28px;
  margin-bottom: 20px;
}

.ss-hero h1 {
  margin: 0 0 8px;
  font-size: clamp(24px, 3vw, 34px);
  line-height: 1.25;
}

.ss-hero p {
  margin: 0 0 18px;
  color: #CBD5E1;
  max-width: 68ch;
}

.ss-stat-val {
  font-size: 26px;
  font-weight: 700;
  color: var(--ss-text);
  margin: 4px 0 0;
}

.ss-stat-lbl {
  font-size: 12px;
  color: var(--ss-text-muted);
  font-weight: 600;
}

/* Typing Engine */
.ss-target-box {
  background: var(--ss-surface-muted);
  border: 1px solid var(--ss-border);
  border-radius: 12px;
  padding: 20px;
  font-family: var(--ss-font-bn);
  font-size: 26px;
  line-height: 1.85;
  letter-spacing: 0.01em;
  min-height: 124px;
  word-wrap: break-word;
  user-select: none;
}

.ss-ch-correct {
  color: var(--ss-emerald-text);
  background: var(--ss-emerald-soft);
  border-radius: 3px;
}

.ss-ch-wrong {
  color: var(--ss-danger);
  background: var(--ss-danger-soft);
  text-decoration: underline wavy var(--ss-danger);
  border-radius: 3px;
}

.ss-ch-current {
  border-bottom: 3px solid var(--ss-emerald);
  background: rgba(5, 150, 105, 0.14);
  border-radius: 3px;
  padding: 0 1px;
}

.ss-input-area {
  width: 100%;
  margin-top: 14px;
  padding: 14px 16px;
  border-radius: 12px;
  border: 2px solid var(--ss-border);
  background: var(--ss-surface);
  color: var(--ss-text);
  font-family: var(--ss-font-bn);
  font-size: 20px;
  resize: none;
}

.ss-input-area:focus {
  outline: none;
  border-color: var(--ss-emerald);
}

/* Visual Bijoy Keyboard */
.ss-kbd-wrap {
  margin-top: 18px;
  background: var(--ss-surface-muted);
  border: 1px solid var(--ss-border);
  border-radius: 14px;
  padding: 14px;
  overflow-x: auto;
}

.ss-kbd-row {
  display: flex;
  gap: 6px;
  margin-bottom: 6px;
  min-width: 720px;
}

.ss-kbd-row:last-child {
  margin-bottom: 0;
}

.ss-key {
  flex: 1;
  min-width: 42px;
  height: 54px;
  background: var(--ss-surface);
  border: 1px solid var(--ss-border);
  border-bottom: 3px solid var(--ss-border);
  border-radius: 8px;
  padding: 4px 6px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  transition: transform 0.08s ease, background-color 0.12s ease, border-color 0.12s ease;
  user-select: none;
}

.ss-key:hover {
  border-color: var(--ss-emerald);
}

.ss-key.w-sm { flex: 1.45; }
.ss-key.w-md { flex: 1.8; }
.ss-key.w-lg { flex: 2.35; }
.ss-key.w-space { flex: 6; align-items: center; justify-content: center; }

.ss-key.is-expected {
  background: var(--ss-emerald-soft);
  border-color: var(--ss-emerald);
  border-bottom-color: var(--ss-emerald);
  box-shadow: 0 0 0 2px rgba(5, 150, 105, 0.25);
}

.ss-key.is-pressed {
  transform: translateY(2px);
  background: var(--ss-emerald);
  color: #FFFFFF;
}

.ss-key-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  color: var(--ss-text-muted);
  font-family: var(--ss-font-mono);
}

.ss-key.is-pressed .ss-key-top,
.ss-key.is-pressed .ss-key-bn {
  color: #FFFFFF;
}

.ss-key-bn {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-family: var(--ss-font-bn);
  font-size: 16px;
  font-weight: 700;
  color: var(--ss-text);
}

.ss-key-bn-shift {
  font-size: 12px;
  font-weight: 500;
  color: var(--ss-text-muted);
}

/* Progress Bar */
.ss-progress-track {
  width: 100%;
  height: 10px;
  background: var(--ss-surface-muted);
  border-radius: 999px;
  overflow: hidden;
  border: 1px solid var(--ss-border);
}

.ss-progress-fill {
  height: 100%;
  background: var(--ss-emerald);
  transition: width 0.25s ease;
}

/* Blogger Standard Blog & Footer Sections */
.ss-blog-wrapper {
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 24px 28px;
}

.ss-post-card {
  background: var(--ss-surface);
  border: 1px solid var(--ss-border);
  border-radius: 14px;
  padding: 24px;
  margin-bottom: 18px;
}

.ss-post-title {
  margin: 0 0 8px;
  font-size: 22px;
}

.ss-post-meta {
  font-size: 13px;
  color: var(--ss-text-muted);
  margin-bottom: 14px;
}

.ss-footer {
  background: var(--ss-surface);
  border-top: 1px solid var(--ss-border);
  padding: 22px 24px;
  margin-top: auto;
}

.ss-footer-inner {
  max-width: 1180px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  font-size: 13px;
  color: var(--ss-text-muted);
}

.ss-linklist ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

.ss-table-wrap {
  overflow-x: auto;
}

table.ss-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

table.ss-table th,
table.ss-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--ss-border);
  text-align: left;
}

table.ss-table th {
  font-size: 12px;
  color: var(--ss-text-muted);
  font-weight: 700;
}

.ss-notice {
  background: var(--ss-emerald-soft);
  color: var(--ss-emerald-text);
  border: 1px solid rgba(5, 150, 105, 0.25);
  border-radius: 10px;
  padding: 12px 14px;
  font-size: 13px;
}

.ss-mobile-tip {
  display: none;
  background: var(--ss-amber-soft);
  color: var(--ss-amber);
  border: 1px solid rgba(217, 119, 6, 0.3);
  border-radius: 10px;
  padding: 10px 14px;
  font-size: 13px;
  margin-bottom: 14px;
}

.ss-backdrop {
  display: none;
}

@media (max-width: 960px) {
  .ss-sidebar {
    position: fixed;
    left: -280px;
    transition: left 0.2s ease;
  }
  .ss-sidebar.is-open {
    left: 0;
  }
  .ss-backdrop.is-open {
    display: block;
    position: fixed;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    z-index: 35;
  }
  .ss-mobile-toggle {
    display: inline-flex;
  }
  .ss-grid-4, .ss-grid-3 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .ss-mobile-tip {
    display: block;
  }
}

@media (max-width: 640px) {
  .ss-grid-4, .ss-grid-3, .ss-grid-2 {
    grid-template-columns: 1fr;
  }
  .ss-content {
    padding: 16px;
  }
  .ss-target-box {
    font-size: 21px;
  }
}

body.script:
