(function () {
  'use strict';

  var SS_DATA = {"keyboardRows":[[{"code":"Backquote","en":"`","enShift":"~","bn":"`","bnShift":"~","bnName":"ব্যাকটিক","bnShiftName":"টিল্ড","finger":"L5"},{"code":"Digit1","en":"1","enShift":"!","bn":"১","bnShift":"!","bnName":"১ (এক)","bnShiftName":"বিস্ময়চিহ্ন","finger":"L5"},{"code":"Digit2","en":"2","enShift":"@","bn":"২","bnShift":"@","bnName":"২ (দুই)","bnShiftName":"@","finger":"L4"},{"code":"Digit3","en":"3","enShift":"#","bn":"৩","bnShift":"#","bnName":"৩ (তিন)","bnShiftName":"#","finger":"L3"},{"code":"Digit4","en":"4","enShift":"$","bn":"৪","bnShift":"৳","bnName":"৪ (চার)","bnShiftName":"৳ (টাকা)","finger":"L2"},{"code":"Digit5","en":"5","enShift":"%","bn":"৫","bnShift":"%","bnName":"৫ (পাঁচ)","bnShiftName":"শতাংশ","finger":"L2"},{"code":"Digit6","en":"6","enShift":"^","bn":"৬","bnShift":"^","bnName":"৬ (ছয়)","bnShiftName":"^","finger":"R2"},{"code":"Digit7","en":"7","enShift":"&","bn":"৭","bnShift":"ঁ","bnName":"৭ (সাত)","bnShiftName":"ঁ (চন্দ্রবিন্দু)","finger":"R2"},{"code":"Digit8","en":"8","enShift":"*","bn":"৮","bnShift":"*","bnName":"৮ (আট)","bnShiftName":"*","finger":"R3"},{"code":"Digit9","en":"9","enShift":"(","bn":"৯","bnShift":"(","bnName":"৯ (নয়)","bnShiftName":"(","finger":"R4"},{"code":"Digit0","en":"0","enShift":")","bn":"০","bnShift":")","bnName":"০ (শূন্য)","bnShiftName":")","finger":"R5"},{"code":"Minus","en":"-","enShift":"_","bn":"-","bnShift":"_","bnName":"হাইফেন","bnShiftName":"আন্ডারস্কোর","finger":"R5"},{"code":"Equal","en":"=","enShift":"+","bn":"=","bnShift":"+","bnName":"সমান","bnShiftName":"যোগ","finger":"R5"},{"code":"Backspace","en":"Backspace","enShift":"Backspace","bn":"⌫","bnShift":"⌫","bnName":"মুছুন","bnShiftName":"মুছুন","finger":"R5","width":"wide-md","isModifier":true}],[{"code":"Tab","en":"Tab","enShift":"Tab","bn":"⇥","bnShift":"⇥","bnName":"ট্যাব","bnShiftName":"ট্যাব","finger":"L5","width":"wide-sm","isModifier":true},{"code":"KeyQ","en":"q","enShift":"Q","bn":"ঙ","bnShift":"ং","bnName":"ঙ","bnShiftName":"ং (অন